from __future__ import annotations

REQUIRED_KEYS = {"message", "actions", "done"}


def has_response_shape(payload: object) -> bool:
    return isinstance(payload, dict) and REQUIRED_KEYS.issubset(payload)

from rusa_agents.response_envelope import has_response_shape


def test_accepts_minimum_response_shape():
    assert has_response_shape({"message": "ok", "actions": [], "done": True})


def test_rejects_non_object():
    assert not has_response_shape(None)

from __future__ import annotations


def summarize_task(task_id: str, status: str, evidence: list[str]) -> dict[str, object]:
    if not task_id.strip() or not status.strip():
        raise ValueError("task_id and status are required")
    return {"task_id": task_id, "status": status, "evidence": list(evidence)}
